'use client';

import React, { useState, useEffect } from 'react';
import { QRCodeSVG } from 'qrcode.react';
import axios from 'axios';
import { supabase } from '@/lib/supabase';
import { getUpiConfigForTransaction } from '@/config/upiConfig';
import { CheckCircle2, AlertCircle, ShieldCheck, Lock, CreditCard, Copy, ArrowRight, Bitcoin, University, Clock } from 'lucide-react';
import { useParams, useSearchParams } from 'next/navigation';

interface PaymentState {
    step: 'billing' | 'payment' | 'verifying' | 'success' | 'failed' | 'expired' | 'manual_upload' | 'verified' | 'review_pending';
    amount: string;
    firstName: string;
    lastName: string;
    email: string;
    phone: string;
    address: string;
    city: string;
    state: string;
    zip: string;
    country: string;
    utr: string;
    error: string;
    screenshot_url?: string;
    paymentMethod: 'upi' | 'card' | 'crypto';
}

export default function PropFirmCheckout() {
    const params = useParams();
    const searchParams = useSearchParams();
    const urlSessionId = params?.orderId as string;

    const queryAmount = searchParams.get('amount');
    const queryName = searchParams.get('name');
    const queryEmail = searchParams.get('email');

    const [state, setState] = useState<PaymentState>({
        step: 'billing',
        amount: '',
        firstName: '',
        lastName: '',
        email: '',
        phone: '',
        address: '',
        city: '',
        state: '',
        zip: '',
        country: 'India',
        utr: '',
        error: '',
        paymentMethod: 'upi' // Default to UPI
    });

    const [sessionId, setSessionId] = useState<string>(urlSessionId || '');
    const [officialOrderId, setOfficialOrderId] = useState<string>('');
    const [copied, setCopied] = useState(false);
    const [timeLeft, setTimeLeft] = useState(15 * 60);

    const { vpa: UPI_ID, merchantName: MERCHANT_NAME } = getUpiConfigForTransaction(sessionId);

    const CHALLENGE_PLANS = [
        { id: '5k', name: '5K Challenge', price: 2499, label: '$5,000 Account' },
        { id: '10k', name: '10K Challenge', price: 4499, label: '$10,000 Account' },
        { id: '20k', name: '20K Challenge', price: 8499, label: '$20,000 Account' },
        { id: '100k', name: '100K Challenge', price: 29999, label: '$100,000 Account' },
    ];

    const [selectedPlan, setSelectedPlan] = useState<string>('');

    // Pre-select plan based on amount if possible, or default
    useEffect(() => {
        if (state.amount && !selectedPlan) {
            // Try to find matching plan
            const match = CHALLENGE_PLANS.find(p => p.price.toString() === state.amount);
            if (match) setSelectedPlan(match.id);
        }
    }, [state.amount]);

    const handlePlanChange = (planId: string) => {
        const plan = CHALLENGE_PLANS.find(p => p.id === planId);
        if (plan) {
            setSelectedPlan(planId);
            setState(prev => ({ ...prev, amount: plan.price.toString() }));
        }
    };

    // Initial Data Fetch
    useEffect(() => {
        if (queryAmount && queryName && queryEmail) {
            const names = queryName.split(' ');
            setState(prev => ({
                ...prev,
                amount: queryAmount,
                firstName: names[0] || '',
                lastName: names.slice(1).join(' ') || '',
                email: queryEmail
            }));
        } else if (urlSessionId) {
            const fetchOrderDetails = async () => {
                try {
                    const { data, error } = await supabase
                        .from('transactions')
                        .select('*')
                        .or(`id.eq.${urlSessionId},session_id.eq.${urlSessionId}`)
                        .single();

                    if (data) {
                        const names = (data.customer_details?.name || '').split(' ');
                        setState(prev => ({
                            ...prev,
                            amount: data.amount.toString(),
                            firstName: names[0] || '',
                            lastName: names.slice(1).join(' ') || '',
                            email: data.customer_details?.email || '',
                            step: data.status === 'verified' ? 'verified' :
                                data.status === 'pending_payment' ? 'payment' : 'billing'
                        }));
                        if (data.order_id) setOfficialOrderId(data.order_id);
                    }
                } catch (err) {
                    console.error("Error fetching order:", err);
                }
            };
            fetchOrderDetails();
            setSessionId(urlSessionId);
        }
    }, [queryAmount, queryName, queryEmail, urlSessionId]);

    // Timer Logic
    useEffect(() => {
        let timer: ReturnType<typeof setInterval>;
        if (state.step === 'payment' && timeLeft > 0) {
            timer = setInterval(() => setTimeLeft(prev => prev - 1), 1000);
        } else if (timeLeft === 0 && state.step === 'payment') {
            setState(prev => ({ ...prev, step: 'expired' }));
        }
        return () => clearInterval(timer);
    }, [state.step, timeLeft]);

    const formatTime = (seconds: number) => {
        const mins = Math.floor(seconds / 60);
        const secs = seconds % 60;
        return `${mins}:${secs.toString().padStart(2, '0')}`;
    };

    // Real-time Supabase Subscription
    useEffect(() => {
        if (!sessionId) return;
        const subscription = supabase
            .channel(`transaction_${sessionId}`)
            .on(
                'postgres_changes',
                {
                    event: 'UPDATE',
                    schema: 'public',
                    table: 'transactions',
                    filter: `session_id=eq.${sessionId}`
                },
                (payload) => {
                    const newStatus = payload.new.status;
                    const newOrderId = payload.new.order_id;

                    if (newStatus === 'verified') {
                        if (newOrderId) setOfficialOrderId(newOrderId);
                        setState(prev => ({ ...prev, step: 'verified' }));

                        // Trigger Receipt Email
                        axios.post('/api/send-receipt', {
                            utr: state.utr,
                            email: state.email,
                            name: `${state.firstName} ${state.lastName}`
                        }).catch(err => console.error('Error sending receipt:', err));

                    } else if (newStatus === 'rejected') {
                        setState(prev => ({ ...prev, step: 'failed', error: 'Payment verification rejected by admin.' }));
                    }
                }
            )
            .subscribe();

        return () => {
            supabase.removeChannel(subscription);
        };
    }, [sessionId]);

    const [termsAccepted, setTermsAccepted] = useState(false);

    const [isLoading, setIsLoading] = useState(false);
    const router = require('next/navigation').useRouter();

    const handlePlaceOrder = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!state.firstName || !state.email || !state.address || !state.city || !state.zip) {
            setState(prev => ({ ...prev, error: 'Please fill in all required fields marked with *' }));
            return;
        }

        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(state.email)) {
            setState(prev => ({ ...prev, error: 'Please enter a valid email address' }));
            return;
        }

        if (!termsAccepted) {
            setState(prev => ({ ...prev, error: 'You must accept the terms and conditions to proceed.' }));
            return;
        }

        setIsLoading(true);

        try {
            // Save transaction details to Supabase
            const { error: dbError } = await supabase
                .from('transactions')
                .upsert([{
                    session_id: sessionId,
                    amount: state.amount,
                    status: 'pending_payment',
                    customer_details: {
                        name: `${state.firstName} ${state.lastName}`,
                        email: state.email,
                        phone: state.phone,
                        address: state.address,
                        city: state.city,
                        zip: state.zip,
                        country: state.country
                    }
                }], { onConflict: 'session_id' });

            if (dbError) {
                console.error('Error saving order:', dbError);
                setState(prev => ({ ...prev, error: 'Failed to create order. Please try again.' }));
                setIsLoading(false);
                return;
            }

            // Redirect to the "Real Payment Page"
            router.push(`/secure-checkout/${sessionId}?mode=payment`);

        } catch (err) {
            console.error('Unexpected error:', err);
            setState(prev => ({ ...prev, error: 'An unexpected error occurred.' }));
            setIsLoading(false);
        }
    };

    const handleVerify = async () => {
        if (!state.utr || state.utr.length !== 12) {
            setState(prev => ({ ...prev, error: 'UTR number must be exactly 12 digits' }));
            return;
        }

        setState(prev => ({ ...prev, step: 'verifying', error: '' }));

        // 1. Check local unique UTR
        try {
            const { data: existingTxn, error: checkError } = await supabase
                .from('transactions')
                .select('*')
                .eq('utr', state.utr)
                .eq('status', 'verified')
                .single();

            if (checkError && checkError.code !== 'PGRST116') {
                setState(prev => ({ ...prev, step: 'failed', error: 'Error checking transaction status' }));
                return;
            }

            if (existingTxn) {
                setState(prev => ({ ...prev, step: 'failed', error: 'This UTR has already been used for a verified payment.' }));
                return;
            }
        } catch (err) {
            console.error('Unexpected error checking UTR:', err);
        }

        // 2. Poll Backend
        let attempts = 0;
        const maxAttempts = 24; // 2 minutes approx (5s interval)
        const pollInterval = 5000;

        const checkPayment = async () => {
            try {
                attempts++;
                const response = await axios.post('/api/verify-payment', {
                    utr: state.utr,
                    amount: state.amount,
                    orderId: sessionId,
                    email: state.email,
                    name: `${state.firstName} ${state.lastName}`
                });

                if (response.data.success) {
                    setState(prev => ({ ...prev, step: 'success' }));
                    return true;
                }

                // If not success, check attempts
                if (attempts >= maxAttempts) {
                    setState(prev => ({ ...prev, step: 'manual_upload', error: '' }));
                    return true;
                }
                return false;
            } catch (err: any) {
                console.error('Verification error:', err);
                if (attempts >= maxAttempts) {
                    setState(prev => ({ ...prev, step: 'failed', error: 'Server unavailable. Please try again or contact support.' }));
                    return true;
                }
                return false;
            }
        };

        const poll = async () => {
            const stop = await checkPayment();
            if (!stop) {
                setTimeout(poll, pollInterval);
            }
        };
        poll();
    };

    const copyToClipboard = (text: string) => {
        navigator.clipboard.writeText(text);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
    };

    const upiUrl = `upi://pay?pa=${UPI_ID}&pn=${encodeURIComponent(MERCHANT_NAME)}&am=${state.amount}&cu=INR`;

    return (
        <div className="min-h-screen bg-[#F4F6F8] font-sans text-slate-900">
            {/* Header */}
            <div className="bg-white border-b border-slate-200 sticky top-0 z-50">
                <div className="container mx-auto px-4 lg:px-8 h-16 flex items-center justify-between">
                    <img src="/shark-logo-full.png" alt="Shark Funded" className="h-8 object-contain" />
                    <div className="flex items-center gap-2 text-slate-500 text-sm">
                        <Lock size={14} />
                        <span className="hidden sm:inline">Secure Checkout</span>
                    </div>
                </div>
            </div>

            <div className="container mx-auto px-4 lg:px-8 py-8 lg:py-12">
                <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 lg:gap-12">

                    {/* LEFT COLUMN: Billing Details */}
                    <div className="lg:col-span-7 space-y-8">
                        {state.step === 'billing' ? (
                            <form onSubmit={handlePlaceOrder} className="bg-white p-6 lg:p-8 rounded-xl shadow-sm border border-slate-100">
                                <h2 className="text-xl font-bold mb-6 text-slate-800 flex items-center gap-2">
                                    <span className="w-6 h-6 rounded-full bg-indigo-600 text-white text-xs flex items-center justify-center">1</span>
                                    Billing Details
                                </h2>

                                <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                                    <div>
                                        <label className="block text-sm font-medium text-slate-700 mb-1.5">First Name <span className="text-red-500">*</span></label>
                                        <input
                                            type="text"
                                            required
                                            className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 transition-all outline-none"
                                            value={state.firstName}
                                            onChange={e => setState({ ...state, firstName: e.target.value })}
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-slate-700 mb-1.5">Last Name</label>
                                        <input
                                            type="text"
                                            className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 transition-all outline-none"
                                            value={state.lastName}
                                            onChange={e => setState({ ...state, lastName: e.target.value })}
                                        />
                                    </div>
                                    <div className="md:col-span-2">
                                        <label className="block text-sm font-medium text-slate-700 mb-1.5">Country / Region <span className="text-red-500">*</span></label>
                                        <select
                                            className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 transition-all outline-none"
                                            value={state.country}
                                            onChange={e => setState({ ...state, country: e.target.value })}
                                        >
                                            <option value="India">India</option>
                                            <option value="United States">United States</option>
                                            <option value="United Kingdom">United Kingdom</option>
                                            <option value="Canada">Canada</option>
                                            <option value="Australia">Australia</option>
                                            {/* Add more countries as needed */}
                                        </select>
                                    </div>
                                    <div className="md:col-span-2">
                                        <label className="block text-sm font-medium text-slate-700 mb-1.5">Street Address <span className="text-red-500">*</span></label>
                                        <input
                                            type="text"
                                            required
                                            placeholder="House number and street name"
                                            className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 transition-all outline-none mb-3"
                                            value={state.address}
                                            onChange={e => setState({ ...state, address: e.target.value })}
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-slate-700 mb-1.5">Town / City <span className="text-red-500">*</span></label>
                                        <input
                                            type="text"
                                            required
                                            className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 transition-all outline-none"
                                            value={state.city}
                                            onChange={e => setState({ ...state, city: e.target.value })}
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-slate-700 mb-1.5">Postcode / ZIP <span className="text-red-500">*</span></label>
                                        <input
                                            type="text"
                                            required
                                            className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 transition-all outline-none"
                                            value={state.zip}
                                            onChange={e => setState({ ...state, zip: e.target.value })}
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-slate-700 mb-1.5">Phone <span className="text-red-500">*</span></label>
                                        <input
                                            type="tel"
                                            required
                                            className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 transition-all outline-none"
                                            value={state.phone}
                                            onChange={e => setState({ ...state, phone: e.target.value })}
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-slate-700 mb-1.5">Email address <span className="text-red-500">*</span></label>
                                        <input
                                            type="email"
                                            required
                                            className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 transition-all outline-none"
                                            value={state.email}
                                            onChange={e => setState({ ...state, email: e.target.value })}
                                        />
                                    </div>
                                </div>

                                {state.error && (
                                    <div className="mt-6 p-4 bg-red-50 text-red-600 rounded-lg flex items-center gap-2 border border-red-100 text-sm font-medium">
                                        <AlertCircle size={16} />
                                        {state.error}
                                    </div>
                                )}
                            </form>
                        ) : state.step === 'success' || state.step === 'verified' ? (
                            <div className="bg-white p-12 rounded-xl shadow-sm border border-emerald-100 text-center flex flex-col items-center">
                                <div className="w-20 h-20 bg-emerald-100 rounded-full flex items-center justify-center mb-6 text-emerald-600">
                                    <CheckCircle2 size={40} />
                                </div>
                                <h2 className="text-2xl font-bold text-slate-900 mb-2">Payment Successful!</h2>
                                <p className="text-slate-500 mb-8 max-w-md">
                                    Your order has been verified successfully. You will receive an email confirmation shortly.
                                </p>
                                {officialOrderId && (
                                    <div className="bg-emerald-50 px-6 py-4 rounded-lg border border-emerald-200 mb-8">
                                        <p className="text-sm text-emerald-700 font-medium opacity-80 mb-1">Order ID</p>
                                        <p className="text-xl font-bold text-emerald-800 font-mono tracking-wide">{officialOrderId}</p>
                                    </div>
                                )}
                                <button className="px-8 py-3 bg-slate-900 text-white rounded-lg font-medium hover:bg-slate-800 transition-all">
                                    Return to Home
                                </button>
                            </div>
                        ) : (
                            <div className="bg-white p-6 lg:p-8 rounded-xl shadow-sm border border-slate-100">
                                {/* PAYMENT STEP UI (UPI QR Code usually) */}
                                <div className="flex items-center justify-between mb-8">
                                    <div>
                                        <h2 className="text-xl font-bold text-slate-900 mb-1">Complete Your Payment</h2>
                                        <p className="text-slate-500 text-sm">Scan the QR code below using any UPI app</p>
                                    </div>
                                    <div className="inline-flex items-center gap-1.5 px-3 py-1 bg-amber-50 text-amber-700 rounded-full text-xs font-bold border border-amber-100">
                                        <Clock size={12} className="animate-pulse" />
                                        <span>{formatTime(timeLeft)}</span>
                                    </div>
                                </div>

                                <div className="flex flex-col items-center justify-center">
                                    <div className="p-4 bg-white rounded-2xl shadow-lg border border-slate-100 mb-6 relative group cursor-pointer" onClick={() => copyToClipboard(upiUrl)}>
                                        <QRCodeSVG value={upiUrl} size={220} level="L" />
                                        {copied && (
                                            <div className="absolute inset-0 bg-white/90 flex items-center justify-center rounded-xl backdrop-blur-sm">
                                                <div className="flex items-center gap-2 text-emerald-600 font-bold bg-emerald-50 px-4 py-2 rounded-full shadow-sm">
                                                    <CheckCircle2 size={16} /> Copied
                                                </div>
                                            </div>
                                        )}
                                    </div>

                                    <div className="flex items-center gap-2 mb-8 w-full max-w-xs">
                                        <div className="flex-1 bg-slate-100 px-4 py-2.5 rounded-lg text-sm font-mono text-slate-700 text-center truncate border border-slate-200">
                                            {UPI_ID}
                                        </div>
                                        <button onClick={() => copyToClipboard(UPI_ID)} className="bg-indigo-50 text-indigo-600 hover:bg-indigo-100 p-2.5 rounded-lg transition-colors border border-indigo-100">
                                            <Copy size={18} />
                                        </button>
                                    </div>

                                    <div className="w-full max-w-md bg-slate-50 p-6 rounded-xl border border-slate-200">
                                        <label className="block text-sm font-bold text-slate-700 mb-2">Enter UTR Reference Number</label>
                                        <div className="flex gap-2">
                                            <input
                                                type="text"
                                                className="flex-1 px-4 py-3 bg-white border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none font-mono text-lg placeholder:text-slate-300"
                                                placeholder="XXXXXXXXXXXX"
                                                value={state.utr}
                                                onChange={e => setState({ ...state, utr: e.target.value })}
                                                maxLength={12}
                                            />
                                            <button
                                                onClick={handleVerify}
                                                disabled={state.step === 'verifying'}
                                                className="px-6 py-3 bg-indigo-600 text-white rounded-lg font-bold hover:bg-indigo-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed shadow-sm hover:shadow-indigo-200 min-w-[100px]"
                                            >
                                                {state.step === 'verifying' ? <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin mx-auto" /> : 'Verify'}
                                            </button>
                                        </div>
                                        {state.error && (
                                            <div className="mt-3 text-red-600 text-sm flex items-center gap-1.5 bg-red-50 p-2 rounded border border-red-100">
                                                <AlertCircle size={14} /> {state.error}
                                            </div>
                                        )}
                                    </div>

                                    <div className="mt-8">
                                        <p className="text-center text-xs font-bold text-slate-400 uppercase tracking-wider mb-4">Accepted Payment Apps</p>
                                        <div className="flex items-center justify-center gap-6 opacity-60 grayscale hover:grayscale-0 transition-all duration-300">
                                            <img src="https://static.cdnlogo.com/logos/p/6/paytm.svg" alt="Paytm" className="h-5 object-contain" />
                                            <img src="https://static.cdnlogo.com/logos/p/25/phonepe.svg" alt="PhonePe" className="h-6 object-contain" />
                                            <img src="https://static.cdnlogo.com/logos/g/80/google-pay.png" alt="Google Pay" className="h-6 object-contain" />
                                        </div>
                                    </div>
                                </div>
                            </div>
                        )}
                    </div>

                    {/* RIGHT COLUMN: Order Summary */}
                    <div className="lg:col-span-5 space-y-6">
                        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 sticky top-24">
                            <h2 className="text-xl font-bold mb-6 text-slate-800 flex items-center gap-2">
                                <span className="w-6 h-6 rounded-full bg-slate-200 text-slate-600 text-xs flex items-center justify-center">2</span>
                                Your Order
                            </h2>

                            <div className="space-y-4 mb-6">
                                <div className="flex justify-between items-center text-sm">
                                    <span className="text-slate-600 font-medium">Product</span>
                                    <span className="text-slate-600 font-medium">Subtotal</span>
                                </div>
                                <div className="border-t border-slate-100 my-2"></div>
                                <div className="flex justify-between items-start gap-4">
                                    <div className="flex-1">
                                        <select
                                            value={selectedPlan}
                                            onChange={(e) => handlePlanChange(e.target.value)}
                                            className="w-full p-2 bg-slate-50 border border-slate-200 rounded-lg text-sm font-medium text-slate-700 outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500"
                                            disabled={state.step !== 'billing'}
                                        >
                                            <option value="" disabled>Select Plan</option>
                                            {CHALLENGE_PLANS.map(plan => (
                                                <option key={plan.id} value={plan.id}>
                                                    {plan.label} - ₹{plan.price.toLocaleString()}
                                                </option>
                                            ))}
                                            {!CHALLENGE_PLANS.find(p => p.id === selectedPlan) && state.amount && (
                                                <option value="custom">Custom Amount - ₹{Number(state.amount).toLocaleString()}</option>
                                            )}
                                        </select>
                                    </div>
                                    <span className="text-slate-800 font-bold whitespace-nowrap mt-2">₹{Number(state.amount).toLocaleString()}</span>
                                </div>
                                <div className="border-t border-slate-100 my-2"></div>
                                <div className="flex justify-between items-center text-lg font-bold">
                                    <span className="text-slate-900">Total</span>
                                    <span className="text-indigo-600">₹{Number(state.amount).toLocaleString()}</span>
                                </div>
                            </div>

                            {/* Payment Methods */}
                            <div className="space-y-4 mb-8">
                                <p className="text-sm font-medium text-slate-700 mb-2">Select Payment Method</p>

                                <label className={`flex items-center p-4 border rounded-lg cursor-pointer transition-all ${state.paymentMethod === 'upi' ? 'border-indigo-600 bg-indigo-50' : 'border-slate-200 hover:border-slate-300'}`}>
                                    <input
                                        type="radio"
                                        name="payment"
                                        className="w-4 h-4 text-indigo-600 accent-indigo-600"
                                        checked={state.paymentMethod === 'upi'}
                                        onChange={() => setState({ ...state, paymentMethod: 'upi' })}
                                    />
                                    <span className="ml-3 flex-1 font-medium text-slate-900">UPI / QR Code</span>
                                    <University className="w-5 h-5 text-slate-400" />
                                </label>

                                <label className={`flex items-center p-4 border rounded-lg cursor-pointer transition-all ${state.paymentMethod === 'card' ? 'border-indigo-600 bg-indigo-50' : 'border-slate-200 hover:border-slate-300'}`}>
                                    <input
                                        type="radio"
                                        name="payment"
                                        className="w-4 h-4 text-indigo-600 accent-indigo-600"
                                        checked={state.paymentMethod === 'card'}
                                        onChange={() => setState({ ...state, paymentMethod: 'card' })}
                                    />
                                    <span className="ml-3 flex-1 font-medium text-slate-900">Credit Card</span>
                                    <CreditCard className="w-5 h-5 text-slate-400" />
                                </label>

                                <label className={`flex items-center p-4 border rounded-lg cursor-pointer transition-all ${state.paymentMethod === 'crypto' ? 'border-indigo-600 bg-indigo-50' : 'border-slate-200 hover:border-slate-300'}`}>
                                    <input
                                        type="radio"
                                        name="payment"
                                        className="w-4 h-4 text-indigo-600 accent-indigo-600"
                                        checked={state.paymentMethod === 'crypto'}
                                        onChange={() => setState({ ...state, paymentMethod: 'crypto' })}
                                    />
                                    <span className="ml-3 flex-1 font-medium text-slate-900">Crypto (USDT/BTC)</span>
                                    <Bitcoin className="w-5 h-5 text-slate-400" />
                                </label>
                            </div>

                            {state.paymentMethod !== 'upi' && (
                                <div className="mb-4 p-3 bg-amber-50 text-amber-700 text-xs rounded border border-amber-100 flex gap-2">
                                    <AlertCircle size={14} className="shrink-0 mt-0.5" />
                                    This payment method is currently unavailable. Please use UPI.
                                </div>
                            )}

                            <div className="flex items-start gap-3 mb-6">
                                <input
                                    type="checkbox"
                                    id="terms"
                                    className="mt-1 w-4 h-4 text-indigo-600 rounded border-gray-300 accent-indigo-600"
                                    checked={termsAccepted}
                                    onChange={(e) => setTermsAccepted(e.target.checked)}
                                />
                                <label htmlFor="terms" className="text-xs text-slate-500">
                                    I have read and agree to the website <a href="#" className="text-indigo-600 hover:underline">terms and conditions</a>.
                                </label>
                            </div>

                            <button
                                onClick={handlePlaceOrder}
                                disabled={state.step !== 'billing' || isLoading}
                                className={`w-full py-4 rounded-xl font-bold text-white shadow-lg transition-all flex items-center justify-center gap-2
                                    ${state.step === 'success' ? 'bg-emerald-500' : 'bg-indigo-600 hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed'}
                                `}
                            >
                                {isLoading ? (
                                    <>Processing...</>
                                ) : state.step === 'success' ? (
                                    <>Order Verified <CheckCircle2 size={18} /></>
                                ) : (
                                    <>Place Order <ArrowRight size={18} /></>
                                )}
                            </button>

                            <div className="mt-6 flex items-center justify-center gap-2 text-slate-400">
                                <ShieldCheck size={14} />
                                <span className="text-[10px] uppercase font-bold tracking-wider">Secure SSL Encrypted Platform</span>
                            </div>

                        </div>
                    </div>

                </div>
            </div>
        </div >
    );
}
